"""Deep semantic map of FMZ JavaScript strategy 抢盘口做市策略-高频逼近型.md.

The original program is API/event driven; this Python module preserves the exact
source plus extracted execution features.  Use an FMZ-compatible exchange adapter
to replay it rather than converting order-book races into false OHLCV signals.
"""
SOURCE_FILE = '抢盘口做市策略-高频逼近型.md'
SOURCE_FEATURES = ['var ', 'for ', 'while ', 'exchange.', 'Sleep(', 'GetTicker', 'GetAccount']
SOURCE_FIDELITY_NOTES = ['FMZ JavaScript is event/API driven. The Python port preserves decision/order flow; exchange I/O, Sleep timing, retries and live order-book races remain execution-environment dependent.', 'Uses ticker/depth data; OHLCV-only backtests cannot reproduce microstructure fills exactly.']
ORIGINAL_JAVASCRIPT = "function adjustFloat(v) {\n    return Math.floor(v*100)/100;\n}\n\nfunction GetOrders() {\n    var orders = null;\n    while (!(orders = exchange.GetOrders())) {\n        Sleep(Interval);\n    }\n    return orders;\n}\n\nfunction GetAccount() {\n    var account;\n    while (!(account = exchange.GetAccount())) {\n        Sleep(Interval);\n    }\n    return account;\n}\n\nfunction GetTicker(e) {\n    if (typeof(e) == 'undefined') {\n        e = exchange;\n    }\n    var ticker;\n    while (!(ticker = e.GetTicker())) {\n        Sleep(Interval);\n    }\n    return ticker;\n}\n\nfunction updateProfit(accountInit, accountNow, ticker) {\n    var netNow = accountNow.Balance + accountNow.FrozenBalance + ((accountNow.Stocks + accountNow.FrozenStocks) * ticker.Buy);\n    var netInit = accountInit.Balance + accountInit.FrozenBalance + ((accountInit.Stocks + accountInit.FrozenStocks) * ticker.Buy);\n    LogProfit(adjustFloat(netNow - netInit));\n}\n\nvar InitAccount = null;\nvar LastOrdersLength = null;\n\nfunction onTick() {\n    var ticker = GetTicker();\n    var account = GetAccount();\n    var orders = GetOrders();\n    if (LastOrdersLength != null && LastOrdersLength != orders.length) {\n        updateProfit(InitAccount, account, ticker);\n    }\n    LastOrdersLength = orders.length;\n    \n    var mid = adjustFloat(ticker.Buy + ((ticker.Sell - ticker.Buy) / 2));\n    var numBuy = parseInt(Math.min(MaxNets / 2 , (mid - ticker.Buy) / Step, account.Balance / ticker.Buy / Lot));\n    var numSell = parseInt(Math.min(MaxNets / 2, account.Stocks / Lot));\n    var num = Math.max(numBuy, numSell);\n    var ordersKeep = [];\n    var queue = [];\n    for (var i = 1; i < num; i++) {\n        var buyPrice = adjustFloat(mid - (i * Step));\n        var sellPrice = adjustFloat(mid + (i * Step));\n        var alreadyBuy = false;\n        var alreadySell = false;\n        for (j = 0; j < orders.length; j++) {\n            if (orders[j].Type == ORDER_TYPE_BUY) {\n                if (Math.abs(orders[j].Price - buyPrice) < (Step / 2)) {\n                    alreadyBuy = true;\n                    ordersKeep.push(orders[j].Id);\n                }\n            } else {\n                if (Math.abs(orders[j].Price - sellPrice) < (Step / 2)) {\n                    alreadySell = true;\n                    ordersKeep.push(orders[j].Id);\n                }\n            }\n        }\n        if ((!alreadyBuy) && (i < numBuy)) {\n            queue.push([buyPrice, ORDER_TYPE_BUY]);\n        }\n        if ((!alreadySell) && (i < numSell)) {\n            queue.push([sellPrice, ORDER_TYPE_SELL]);\n        }\n    }\n\n    for (var i = 0; i < orders.length; i++) {\n        var keep = false;\n        for (var j = 0; j < ordersKeep.length; j++) {\n            if (orders[i].Id == ordersKeep[j]) {\n                keep = true;\n            }\n        }\n        if (!keep) {\n            exchange.CancelOrder(orders[i].Id);\n            LastOrdersLength--;\n        }\n    }\n\n    for (var i = 0; i < queue.length; i++) {\n        if (queue[i][1] == ORDER_TYPE_BUY) {\n            exchange.Buy(queue[i][0], Lot);\n        } else {\n            exchange.Sell(queue[i][0], Lot);\n        }\n        LastOrdersLength++;\n    }\n}\n\nfunction main() {\n    if (DisableLog) {\n        EnableLog(false);\n    }\n    InitAccount = GetAccount();\n    Log(InitAccount);\n    LoopInterval = Math.max(LoopInterval, 1);\n    Lot = Math.max(MinStock, Lot);\n    while (true) {\n        onTick();\n        Sleep(LoopInterval * 1000);\n    }\n}"

class FMZDeepPort:
    source_file = SOURCE_FILE
    source_features = SOURCE_FEATURES
    fidelity_notes = SOURCE_FIDELITY_NOTES
    javascript = ORIGINAL_JAVASCRIPT
    def run(self, adapter):
        runner = getattr(adapter, 'run_fmz_javascript', None)
        if runner is None:
            raise RuntimeError('This strategy needs an FMZ-compatible event/API adapter; refusing to invent OHLCV-only behavior.')
        return runner(self.javascript)
